import{_ as t,b as o,o as p,c,e as a,j as n,k as e,a as l}from"./app-631b6948.js";const u={},r=l(`<h1 id="null-safety" tabindex="-1"><a class="header-anchor" href="#null-safety" aria-hidden="true">#</a> Null safety</h1><p>Null safety makes the absence of a value explicit in the type system. A value of type <code>str</code> can never be <code>null</code>. A value of type <code>str?</code> can either contain a <code>str</code> or <code>null</code>. buzz requires you to mark nullable values with a <code>?</code>, and it will not let you use them as non-null values until you handle the <code>null</code> case. This greatly reduces runtime errors caused by forgotten <code>null</code> checks. The language provides several ways to handle nullable values depending on whether you want a safe fallback or you want to assert that a value must exist.</p><h2 id="declaring-nullable-values" tabindex="-1"><a class="header-anchor" href="#declaring-nullable-values" aria-hidden="true">#</a> Declaring nullable values</h2><p>Use <code>T?</code> when a value may be absent.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">userName</span><span class="token punctuation">:</span> <span class="token keyword">str</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">giann</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>
<span class="token keyword">final</span> <span class="token variable">nickname</span><span class="token punctuation">:</span> <span class="token keyword">str</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token null constant">null</span><span class="token punctuation">;</span>
</code></pre></div><p>Once a variable is nullable, you must unwrap it, provide a fallback, or propagate the optional result before using it as a plain <code>str</code>.</p><h2 id="for-default-values" tabindex="-1"><a class="header-anchor" href="#for-default-values" aria-hidden="true">#</a> <code>??</code> for default values</h2><p>Use the null coalescing operator when you want a fallback value.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">configuredPort</span><span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token null constant">null</span><span class="token punctuation">;</span>
<span class="token keyword">final</span> <span class="token variable">port</span><span class="token punctuation">:</span> <span class="token keyword">int</span> <span class="token operator">=</span> configuredPort <span class="token operator">??</span> <span class="token number">3000</span><span class="token punctuation">;</span>
</code></pre></div><p><code>left ?? right</code> returns <code>left</code> when it is not <code>null</code>, otherwise it returns <code>right</code>. This is usually the simplest tool when there is an obvious default.</p><h2 id="for-optional-chaining" tabindex="-1"><a class="header-anchor" href="#for-optional-chaining" aria-hidden="true">#</a> <code>?.</code> for optional chaining</h2><p>Use <code>?.</code> when you want to access a field, method, or subscript only if the value exists.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">numbers</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token keyword">int</span><span class="token punctuation">]</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token punctuation">[</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span> <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token keyword">final</span> <span class="token variable">count</span> <span class="token operator">=</span> numbers<span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">len</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// -&gt; 3</span>

<span class="token keyword">final</span> <span class="token variable">missingNumbers</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token keyword">int</span><span class="token punctuation">]</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token null constant">null</span><span class="token punctuation">;</span>
<span class="token keyword">final</span> <span class="token variable">missingCount</span> <span class="token operator">=</span> missingNumbers<span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">len</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// -&gt; null</span>
</code></pre></div><p>If the value on the left is <code>null</code>, the whole expression becomes <code>null</code>. This makes optional chaining useful when a missing value is expected and should simply propagate.</p><p>Optional chaining can be combined:</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">object</span> <span class="token class-name">Me</span> <span class="token punctuation">{</span>
    list<span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token keyword">int</span><span class="token punctuation">]</span><span class="token operator">?</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span>

<span class="token keyword">final</span> <span class="token variable">me</span><span class="token punctuation">:</span> <span class="token class-name">Me</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token punctuation">.</span><span class="token punctuation">{</span>
    list <span class="token operator">=</span> <span class="token punctuation">[</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span> <span class="token punctuation">]</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">final</span> <span class="token variable">count</span> <span class="token operator">=</span> me<span class="token operator">?</span><span class="token punctuation">.</span>list<span class="token operator">?</span><span class="token punctuation">.</span><span class="token function">len</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// -&gt; 3</span>
</code></pre></div><h2 id="if-value-name-for-conditional-unwrapping" tabindex="-1"><a class="header-anchor" href="#if-value-name-for-conditional-unwrapping" aria-hidden="true">#</a> <code>if (value -&gt; name)</code> for conditional unwrapping</h2><p>Use <code>if</code> unwrapping when you want one branch for the non-null case and another for the <code>null</code> case.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">aStringOrNull</span><span class="token punctuation">:</span> <span class="token keyword">str</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">hello</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span>aStringOrNull <span class="token operator">-&gt;</span> aString<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">{</span>aString<span class="token interpolation-punctuation punctuation">}</span></span><span class="token string"> is not null</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span>
    <span class="token namespace">std<span class="token punctuation">\\</span></span><span class="token function">print</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">aString was null</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Inside the <code>if</code> branch, <code>aString</code> is a plain <code>str</code>, not a <code>str?</code>. This is the most direct form when the code path depends on whether the value exists.</p><h2 id="for-force-unwrapping" tabindex="-1"><a class="header-anchor" href="#for-force-unwrapping" aria-hidden="true">#</a> <code>!</code> for force unwrapping</h2><p>Use <code>!</code> when you know a nullable value is not <code>null</code> and you want the wrapped value directly.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">aStringOrNull</span><span class="token punctuation">:</span> <span class="token keyword">str</span><span class="token operator">?</span> <span class="token operator">=</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">hello</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>
<span class="token keyword">final</span> <span class="token variable">unwrapped</span><span class="token punctuation">:</span> <span class="token keyword">str</span> <span class="token operator">=</span> aStringOrNull<span class="token operator">!</span><span class="token punctuation">;</span>
</code></pre></div><p>If the value is actually <code>null</code>, buzz raises a runtime error. Use <code>!</code> only when the surrounding logic already guarantees the value is present.</p><h2 id="value-as-t-for-safe-casts" tabindex="-1"><a class="header-anchor" href="#value-as-t-for-safe-casts" aria-hidden="true">#</a> <code>value as? T</code> for safe casts</h2><p>Null safety also applies to runtime casts. <code>value as? T</code> attempts the cast and returns <code>T?</code>.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">anything</span><span class="token punctuation">:</span> <span class="token keyword">any</span> <span class="token operator">=</span> <span class="token number">12</span><span class="token punctuation">;</span>

<span class="token keyword">final</span> <span class="token variable">number</span><span class="token punctuation">:</span> <span class="token keyword">int</span><span class="token operator">?</span> <span class="token operator">=</span> anything <span class="token keyword">as?</span> <span class="token keyword">int</span><span class="token punctuation">;</span> <span class="token comment">// -&gt; 12</span>
<span class="token keyword">final</span> <span class="token variable">text</span><span class="token punctuation">:</span> <span class="token keyword">str</span><span class="token operator">?</span> <span class="token operator">=</span> anything <span class="token keyword">as?</span> <span class="token keyword">str</span><span class="token punctuation">;</span>   <span class="token comment">// -&gt; null</span>
<span class="token keyword">final</span> <span class="token variable">safeNumber</span> <span class="token operator">=</span> <span class="token punctuation">(</span>anything <span class="token keyword">as?</span> <span class="token keyword">int</span><span class="token punctuation">)</span> <span class="token operator">??</span> <span class="token number">0</span><span class="token punctuation">;</span>
</code></pre></div><p>This makes <code>as?</code> fit naturally into the rest of the null-safety tools:</p><ul><li>use <code>??</code> to provide a fallback</li><li>use <code>if (value -&gt; name)</code> to branch on success</li><li>use <code>?.</code> to keep propagating the optional result</li></ul><h2 id="value-as-t-for-strict-casts" tabindex="-1"><a class="header-anchor" href="#value-as-t-for-strict-casts" aria-hidden="true">#</a> <code>value as! T</code> for strict casts</h2><p><code>value as! T</code> performs the same runtime cast, but it returns <code>T</code> directly and assumes the cast must succeed.</p><div class="language-buzz" data-ext="buzz"><pre class="language-buzz"><code><span class="token keyword">final</span> <span class="token variable">anything</span><span class="token punctuation">:</span> <span class="token keyword">any</span> <span class="token operator">=</span> <span class="token string-literal"><span class="token string-punctuation punctuation">&quot;</span><span class="token string">hello</span><span class="token string-punctuation punctuation">&quot;</span></span><span class="token punctuation">;</span>

<span class="token keyword">final</span> <span class="token variable">text</span><span class="token punctuation">:</span> <span class="token keyword">str</span> <span class="token operator">=</span> anything <span class="token keyword">as</span><span class="token operator">!</span> <span class="token keyword">str</span><span class="token punctuation">;</span>
<span class="token keyword">final</span> <span class="token variable">size</span> <span class="token operator">=</span> text<span class="token punctuation">.</span><span class="token function">len</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>If the value is not of type <code>T</code>, buzz raises a runtime error. Use <code>as!</code> only when the runtime type is already guaranteed by previous logic.</p><h2 id="choosing-the-right-tool" tabindex="-1"><a class="header-anchor" href="#choosing-the-right-tool" aria-hidden="true">#</a> Choosing the right tool</h2><p>Use these operators when failure is expected and should be handled safely:</p><ul><li><code>??</code></li><li><code>?.</code></li><li><code>if (value -&gt; name)</code></li><li><code>value as? T</code></li></ul><p>Use these operators when failure would mean a bug or a broken assumption:</p><ul><li><code>value!</code></li><li><code>value as! T</code></li></ul>`,38),i=a("code",null,"if (value as name: T)",-1),k={href:"/guide/control-flow.html",target:"_blank",rel:"noopener noreferrer"},d=a("code",null,"any",-1),h={href:"/guide/types.html#any",target:"_blank",rel:"noopener noreferrer"};function g(f,b){const s=o("ExternalLinkIcon");return p(),c("div",null,[r,a("p",null,[n("For "),i,n(" style downcasting, see "),a("a",k,[n("Control flow"),e(s)]),n(". For more about "),d,n(", see "),a("a",h,[n("Types"),e(s)]),n(".")])])}const v=t(u,[["render",g],["__file","null-safety.html.vue"]]);export{v as default};
